return {{["id"]="hud.world3d.size",["title"]=1471882062,["description"]=1481966352,["group"]=2698641059,["default"]=1,["step"]=0.1,["range"]={0.5,1.5},["label"]="Size",["description_text"]="Scale of the whole 3D HUD.",["category"]="3D HUD"},{["id"]="hud.world3d.lock",["title"]=3620446344,["description"]=4166917901,["group"]=2698641059,["default"]=0,["choices"]={2099863214,210218785,2867806537},["label"]="HUD Position",["description_text"]="Where the 3D HUD sits in third person. Body follows your weapon and head. Reticle keeps it on the reticle and moves it to the right while you aim or attack. Beside Reticle keeps it to the right of the reticle. First person and seats always use the right side.",["category"]="3D HUD",["choice_labels"]={"Body","Reticle","Beside Reticle"}},{["id"]="hud.world3d.idle",["title"]=3272212771,["description"]=2700163307,["group"]=2698641059,["default"]=1,["choices"]={2996071234,3154830844,2221272278},["label"]="When Idle",["description_text"]="What the 3D HUD does once the game stops showing weapon info (it shows it while you aim, shoot, reload, switch or open the map). Hide fades it out, Dim keeps it at 30% and Always keeps it fully visible.",["category"]="3D HUD",["choice_labels"]={"Hide","Dim","Always"}},{["id"]="hud.world3d.fire_time",["title"]=3804414019,["description"]=3581489275,["group"]=2698641059,["default"]=5,["step"]=1,["range"]={0,5},["label"]="Time Before Idle",["description_text"]="How many seconds the 3D HUD stays after the last change or action before switching to its When Idle look, from 0 to 5. Actions are aiming, attacking, reloading, stamina recovery and backpack use, and the HUD stays visible while they last. At 0 it switches as soon as an action ends. A change always shows it for at least 1 second.",["category"]="3D HUD"},{["id"]="hud.world3d.tilt_mix",["default"]=0.5,["range"]={0,1}},{["id"]="hud.world3d.tilt_cap",["default"]=15,["range"]={0,80}},{["id"]="hud.world3d.screen_x",["default"]=0.85,["range"]={-5,5}},{["id"]="hud.world3d.screen_y",["default"]=0,["range"]={-5,5}},{["id"]="hud.world3d.stratagem_screen_x",["default"]=0,["range"]={-5,5}},{["id"]="hud.world3d.stratagem_screen_y",["default"]=-0.6,["range"]={-5,5}},{["id"]="hud.world3d.aim_x",["default"]=0.7,["range"]={-5,5}},{["id"]="hud.world3d.aim_y",["default"]=0.65,["range"]={-5,5}},{["id"]="hud.world3d.aim_radius",["default"]=0.002,["range"]={0,0.5}},{["id"]="hud.world3d.aim_tau",["default"]=0.05,["range"]={0,2}},{["id"]="hud.world3d.aim_ceiling",["default"]=0.5,["range"]={0,2}},{["id"]="hud.world3d.aim_body_x",["default"]=1.3,["range"]={-5,5}},{["id"]="hud.world3d.aim_body_y",["default"]=-0.5,["range"]={-5,5}},{["id"]="hud.world3d.aim_body_radius",["default"]=0,["range"]={0,0.5}},{["id"]="hud.world3d.aim_body_tau",["default"]=0.1,["range"]={0,2}},{["id"]="hud.world3d.aim_body_ceiling",["default"]=0.5,["range"]={0,2}},{["id"]="hud.world3d.weapon_x",["default"]=1.1,["range"]={-5,5}},{["id"]="hud.world3d.weapon_y",["default"]=-0.5,["range"]={-5,5}},{["id"]="hud.world3d.weapon_radius",["default"]=0,["range"]={0,0.5}},{["id"]="hud.world3d.weapon_tau",["default"]=0.1,["range"]={0,2}},{["id"]="hud.world3d.weapon_ceiling",["default"]=0.2,["range"]={0,2}},{["id"]="hud.world3d.stratagem_x",["default"]=0.75,["range"]={-5,5}},{["id"]="hud.world3d.stratagem_y",["default"]=0,["range"]={-5,5}},{["id"]="hud.world3d.stratagem_radius",["default"]=0,["range"]={0,0.5}},{["id"]="hud.world3d.stratagem_tau",["default"]=0.4,["range"]={0,2}},{["id"]="hud.world3d.stratagem_icon_x",["default"]=0.7,["range"]={-5,5}},{["id"]="hud.world3d.stratagem_icon_y",["default"]=0,["range"]={-5,5}},{["id"]="hud.world3d.stratagem_icon_radius",["default"]=0,["range"]={0,0.5}},{["id"]="hud.world3d.stratagem_icon_tau",["default"]=0.15,["range"]={0,2}},{["id"]="hud.weapon3d.opacity",["title"]=2661443765,["description"]=995713527,["group"]=2698641059,["default"]=0.7,["step"]=0.1,["range"]={0.6,1},["label"]="Opacity",["description_text"]="Opacity of the 3D HUD gauges and weapon info. The stratagem list always stays fully visible.",["category"]="3D HUD"},{["id"]="hud.weapon3d.arc",["title"]=1274175364,["description"]=3442472282,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Weapon Gauges",["description_text"]="Gauges on the weapon panel for the magazine, heat, charge, reload and next-attack progress.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.health",["title"]=491964757,["description"]=3272910115,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Health Gauge",["description_text"]="A health gauge opposite the weapon gauges. It appears when your health changes and fills smoothly like the game's health bar.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.stamina",["title"]=3381695498,["description"]=776955930,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Stamina Gauge",["description_text"]="A thin stamina gauge inside the health gauge, at 80% brightness. It appears while your stamina refills and whenever the health gauge shows.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.pack",["title"]=3834662459,["description"]=2988512217,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Backpack Gauge",["description_text"]="A thin backpack gauge inside the weapon gauges, taken from the game's backpack gauge. It appears when the gauge changes and while the backpack is working.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.layout",["title"]=2584813342,["description"]=2780966384,["group"]=2698641059,["default"]=0,["choices"]={1194359458,3844198845,3555444837,3288235483},["label"]="Gauge Layout",["description_text"]="Which sides the weapon and health gauges sit on. Gauges always fill from the same end on both sides.",["category"]="3D HUD",["choice_labels"]={"Health left, weapon right","Weapon left, health right","Weapon top, health bottom","Health top, weapon bottom"}},{["id"]="hud.weapon3d.ammo",["title"]=452780791,["description"]=3067891472,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Ammo Count",["description_text"]="Rounds left in the magazine, as a number on the weapon panel.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.reserve",["title"]=451966600,["description"]=3232277582,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Spare Magazines",["description_text"]="Number of spare magazines left.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.throwables",["title"]=1009079121,["description"]=4282512968,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Throwable Count",["description_text"]="Your throwable's icon and count next to the spare magazines. Hidden while you hold the throwable, since the ammo count then shows it.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.stims",["title"]=1152012399,["description"]=2854226556,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Stim Count",["description_text"]="Your stim icon and count next to the spare magazines.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.functions",["title"]=3722583536,["description"]=3572699417,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Weapon Function Icons",["description_text"]="Icons for the current settings of the weapon functions you change on the weapon wheel. While you hold a throwable with a fuse time choice, such as Dynamite, it shows the chosen fuse time.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.fire_mode",["title"]=298719059,["description"]=3367026420,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Fire Mode Icon",["description_text"]="Icon for the weapon's current fire mode.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.zeroing",["title"]=3357555945,["description"]=4026194371,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Zeroing Icon",["description_text"]="Icon for the zeroing distance of the scope fitted to the weapon.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.icon_size",["default"]=0.45,["range"]={0.1,1}},{["id"]="hud.weapon3d.ammo_text_size",["default"]=18.5,["range"]={6,60}},{["id"]="hud.weapon3d.count_text_size",["default"]=14,["range"]={6,60}},{["id"]="hud.weapon3d.mode_icon_size",["default"]=0.4,["range"]={0.1,1}},{["id"]="hud.weapon3d.gauge_gap",["default"]=8,["range"]={0,40}},{["id"]="hud.weapon3d.gauge_angle",["default"]=100,["range"]={30,180}},{["id"]="hud.weapon3d.reserve_icon_size",["default"]=0.38,["range"]={0.1,1}},{["id"]="hud.weapon3d.stim_icon_size",["default"]=0.25,["range"]={0.1,1}},{["id"]="hud.weapon3d.cooldown_size",["default"]=0.5,["range"]={0.1,1}},{["id"]="hud.weapon3d.cooldown_gap",["default"]=20,["range"]={0,80}},{["id"]="hud.stratagem3d",["title"]=438378681,["description"]=1437604305,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Stratagem List",["description_text"]="While you enter a stratagem code or hold a stratagem beacon, shows the game's stratagem list in the 3D HUD instead of the screen.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.stratagem3d.pick",["title"]=2360581074,["description"]=281595105,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Pick with Mouse Wheel",["description_text"]="Works only while Stratagem List is on, and only with a mouse - not with a controller. While the list is open, scroll the mouse wheel to pick one; releasing the left mouse button enters it.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.weapon3d.cooldown",["title"]=65594734,["description"]=1569354098,["group"]=2698641059,["default"]=1,["choices"]={"off","on"},["label"]="Stratagem Cooldowns",["description_text"]="Next to the weapon gauges, shows the game's cards for the stratagems you can't use right now (being called in, cooling down, used up or blocked), with the game's own fill and remaining uses. When one is ready again, its card brightens once and then leaves.",["category"]="3D HUD",["choice_labels"]={"off","on"}},{["id"]="hud.stratagem3d.list_x",["default"]=100,["range"]={-1000,1000}},{["id"]="hud.stratagem3d.list_y",["default"]=-100,["range"]={-1000,1000}},{["id"]="hud.stratagem3d.icon_x",["default"]=0,["range"]={-1000,1000}},{["id"]="hud.stratagem3d.icon_y",["default"]=-20,["range"]={-1000,1000}},{["id"]="hud.ammo.ammo",["title"]=452780791,["description"]=2040205881,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Ammo Count",["description_text"]="Adds the rounds left in the magazine as a number to the game's weapon HUD.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}},{["id"]="hud.ammo.functions",["title"]=3722583536,["description"]=592714962,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Weapon Function Icons",["description_text"]="Adds icons for the current settings of the weapon functions to the game's weapon HUD.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}},{["id"]="hud.ammo.fire_mode",["title"]=298719059,["description"]=1835096794,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Fire Mode Icon",["description_text"]="Adds an icon for the weapon's current fire mode next to the game's weapon HUD.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}},{["id"]="hud.ammo.zeroing",["title"]=3357555945,["description"]=2925010036,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Zeroing Icon",["description_text"]="Adds an icon for the zeroing distance of the fitted scope next to the game's weapon HUD.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}},{["id"]="hud.trajectory",["title"]=3236973080,["description"]=2398774772,["group"]=3541488915,["default"]=1,["choices"]={"off",2013128776,4005790058,781302181},["label"]="Trajectory Preview",["description_text"]="While aiming a gun, or holding the throw button with a grenade or stratagem beacon, draws its path and marks where it hits. Guns get a path only for explosive rounds with a clear drop. For explosive rounds, the blast radius is painted on the ground and turns the game's warning colour while you stand inside it. If the far end of the line is cut off, turn Anti-Aliasing on or set Render Scale to NATIVE in GRAPHICS.",["category"]="Markers",["choice_labels"]={"off","Trajectory + Blast Radius","Trajectory Only","Marker + Blast Radius"}},{["id"]="hud.trajectory.marker",["title"]=3909533600,["description"]=1867395245,["group"]=3541488915,["default"]=0,["choices"]={1609790743,320920627},["label"]="Impact Marker",["description_text"]="Shape of the marker drawn where the trajectory lands, while Trajectory Preview is on.",["category"]="Markers",["choice_labels"]={"Ring","Brackets"}},{["id"]="hud.throw_distance",["title"]=1904316258,["description"]=3741449447,["group"]=3541488915,["default"]=1,["choices"]={"off","on"},["label"]="Throw Distance",["description_text"]="While you hold the throw button with a grenade or stratagem beacon, shows the distance to where it lands just below that spot, like the game's ping distance.",["category"]="Markers",["choice_labels"]={"off","on"}},{["id"]="hud.attack_area",["title"]=2125888131,["description"]=4260852240,["group"]=3541488915,["default"]=2,["choices"]={"off",4093782765,3126647506},["label"]="Stratagem Indicators",["description_text"]="While you hold a stratagem beacon, shows where its attack will land at the end of the throw path: the blast radius, the scatter area or attack strip, and the approach direction. A called Eagle strike's area stays on the ground until the attack ends, and each incoming shell shows a circle where it will land. The area turns the game's warning colour while you stand inside it. It is an estimate, not an exact damage boundary. Showing many strikes at once can briefly lower the frame rate.",["category"]="Markers",["choice_labels"]={"off","My Stratagems","All Stratagems"}},{["id"]="game.reticle",["title"]=3985291576,["description"]=1847489654,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Game Reticle (AMR, Backpack-Fed)",["description_text"]="Lets the game draw its own reticle for the Anti-Materiel Rifle in third person, and in first person for backpack-fed weapons without sights (Maxigun, Belt-Fed Grenade Launcher, Cremator). It follows the game's Reticle Visibility setting and applies to weapons that spawn after the change.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}},{["id"]="hud.squad",["title"]=3918004437,["description"]=2071690689,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Squad Status",["description_text"]="Shows skulls, recent map pings, boosters and each squadmate's stratagem calls. Calls sit beside the gear; your own status attaches to the weapon or health display.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}},{["id"]="hud.corpse",["title"]=244896658,["description"]=2162299999,["group"]=3541488915,["default"]=1,["choices"]={"off","on"},["label"]="Death Marker",["description_text"]="Marks the spot where you died with a skull. After your reinforcement lands it stays 15 seconds, or until you reach it.",["category"]="Markers",["choice_labels"]={"off","on"}},{["id"]="hud.reinforce",["title"]=3859154251,["description"]=3437462995,["group"]=3541488915,["default"]=1,["choices"]={"off","on"},["label"]="Enemy Reinforcement Markers",["description_text"]="Marks an enemy that is calling reinforcements, and the spot where they arrive. The marker counts down to the call and to the next wave.",["category"]="Markers",["choice_labels"]={"off","on"}},{["id"]="hud.kill_pulse",["title"]=3008836707,["description"]=2019038856,["group"]=3441939234,["default"]=1,["choices"]={"off","on"},["label"]="Kill Hit Marker",["description_text"]="When your hit kills an enemy, the game's hit marker on the reticle briefly pops bigger.",["category"]="Vanilla HUD",["choice_labels"]={"off","on"}}}
